#version 300 es
precision highp float;
precision highp int;
layout(location = 0) in vec3 in_Pos;
layout(location = 1) in vec3 in_Nor;
layout(location = 2) in vec2 in_UV;
layout(location = 3) in ivec4 in_BoneIndex;
layout(location = 4) in vec4 in_BoneWeight;
layout(location = 5) in vec3 in_Morph;
uniform mat4 u_WV;
uniform mat4 u_WVP;
uniform sampler2D u_Bones;
uniform int u_UseGpuSkin;
out vec3 vs_Pos;
out vec3 vs_Nor;
out vec2 vs_UV;
mat4 boneMat(int i) {
  return mat4(
    texelFetch(u_Bones, ivec2(0, i), 0),
    texelFetch(u_Bones, ivec2(1, i), 0),
    texelFetch(u_Bones, ivec2(2, i), 0),
    texelFetch(u_Bones, ivec2(3, i), 0));
}
void main() {
  vec3 pos = in_Pos + in_Morph;
  vec3 nor = in_Nor;
  if (u_UseGpuSkin != 0) {
    mat4 m = mat4(0.0);
    float wsum = 0.0;
    for (int i = 0; i < 4; ++i) {
      int bi = in_BoneIndex[i];
      float w = in_BoneWeight[i];
      if (w > 0.0 && bi >= 0) {
        m += boneMat(bi) * w;
        wsum += w;
      }
    }
    if (wsum < 0.0001) {
      m = mat4(1.0);
    }
    pos = (m * vec4(pos, 1.0)).xyz;
    nor = mat3(m) * nor;
  }
  gl_Position = u_WVP * vec4(pos, 1.0);
  vs_Pos = (u_WV * vec4(pos, 1.0)).xyz;
  vs_Nor = mat3(u_WV) * nor;
  vs_UV = vec2(in_UV.x, 1.0 - in_UV.y);
}

#version 300 es
precision mediump float;
precision mediump int;
in vec3 vs_Pos;
in vec3 vs_Nor;
in vec2 vs_UV;
layout(location = 0) out vec4 out_Color;
uniform vec3 u_Diffuse;
uniform vec3 u_Ambient;
uniform vec3 u_Specular;
uniform float u_SpecularPower;
uniform float u_Alpha;
uniform vec3 u_LightColor;
uniform vec3 u_LightDir;
uniform int u_TexMode;
uniform sampler2D u_Tex;
uniform int u_ToonTexMode;
uniform sampler2D u_ToonTex;
uniform int u_SphereTexMode;
uniform sampler2D u_SphereTex;
void main() {
  vec3 eyeDir = normalize(vs_Pos);
  vec3 lightDir = normalize(-u_LightDir);
  vec3 nor = normalize(vs_Nor);
  float ln = clamp(dot(nor, lightDir) + 0.5, 0.0, 1.0);
  vec3 color = clamp(u_Diffuse * u_LightColor + u_Ambient, 0.0, 1.0);
  float alpha = u_Alpha;
  if (u_TexMode != 0) {
    vec4 texColor = texture(u_Tex, vs_UV);
    color *= texColor.rgb;
    if (u_TexMode == 2) { alpha *= texColor.a; }
  }
  if (alpha < 0.02) { discard; }
  if (u_SphereTexMode != 0) {
    vec2 spUV = vec2(nor.x * 0.5 + 0.5, nor.y * 0.5 + 0.5);
    vec3 spColor = texture(u_SphereTex, spUV).rgb;
    if (u_SphereTexMode == 1) { color *= spColor; }
    else { color += spColor; }
  }
  if (u_ToonTexMode != 0) {
    color *= texture(u_ToonTex, vec2(0.0, 1.0 - ln)).rgb;
  }
  if (u_SpecularPower > 0.0) {
    vec3 halfVec = normalize(eyeDir + lightDir);
    color += pow(max(0.0, dot(halfVec, nor)), u_SpecularPower) * u_Specular * u_LightColor;
  }
  out_Color = vec4(color, alpha);
}

